mapper.select:
select * from (SELECT distinct A.PARA_CODE paraCode, A.PARA_NAME paraName,
A.UPDATE_TIME updateTime, '' content, B.PARA_DISPLAY_TYPE paraType, null validDate, A.CREATE_USER createUser, A.CREATE_DEPT createDept FROM RSK_ISUP_INDICATOR_PARA A,RSK_ISUP_INDICATOR_PARA_DTL B
A.PARA_CODE = B.PARA_CODE
AND B.PARA_DISPLAY_TYPE = #{paraType}
AND (A.PARA_NAME LIKE CONCAT_ws('', '%',#{paraName}, '%') or A.PARA_CODE LIKE concat_ws('','%',#{paraName},'%'))
UNION ALL SELECT C.PARA_CODE paraCode, C.PARA_NAME paraName, C.UPDATE_TIME updateTime, case when D.VALID_DATE <= STR_TO_DATE(#{NOW()},'%Y-%m-%d') then DATE_FORMAT(D.CONTENT) else '' end content, #{FIX} paraType, D.VALID_DATE validDate, C.CREATE_USER createUser, C.CREATE_DEPT createDept FROM RSK_ISUP_INDICATOR_PARA C ,RSK_ISUP_FIX_RECODE D
C.PARA_CODE = D.PARA_CODE and D.VALID_DATE in (SELECT MAX(RSK_ISUP_FIX_RECODE.VALID_DATE) FROM RSK_ISUP_FIX_RECODE WHERE PARA_CODE = C.PARA_CODE GROUP BY PARA_CODE )
and #{FIX} = #{paraType}
AND (C.PARA_NAME LIKE CONCAT_ws('', '%',#{paraName}, '%') or C.PARA_CODE LIKE concat_ws('','%',#{paraName},'%'))
) ORDER BY updateTime DESC
